/* launch checklist */
.lc-head{display:flex;align-items:center;justify-content:space-between;padding:14px 16px;border-bottom:1px solid var(--line)}
.lc-head .t{font-weight:600;font-size:14px}
.lc-bar{display:flex;gap:2px;height:4px;margin:12px 16px 4px}
.lc-bar i{flex:1;background:var(--line);transition:background-color .35s}
.lc-bar i.pass{background:var(--success)}.lc-bar i.warn{background:var(--accent)}.lc-bar i.fail{background:var(--danger)}
.lc-row{display:flex;align-items:center;gap:12px;padding:8px 16px;font-size:13px;color:var(--text-dim);transition:color .3s}
.lc-row.ran{color:var(--text)}
.lc-row .st{width:16px;height:16px;display:grid;place-items:center;flex:none}
.lc-row .note{display:block;font-size:11px;color:var(--muted)}
.lc-row .r{margin-left:auto;display:flex;align-items:center;gap:8px}
.lc-row .res{font-family:var(--mono);font-weight:700;font-size:10px;text-transform:uppercase}
.res.pass{color:var(--success)}.res.warn{color:var(--accent)}.res.fail{color:var(--danger)}

/* ---------- launch checklist ---------- */
{
  const list = $('#lc-list'), bar = $('#lc-bar'), sum = $('#lc-sum');
  const checks = [['Colour contrast','pass',''],['Alt text on images','warn','2 images missing a description'],['Broken links','fail','1 link returns a 404'],['Heading order','pass',''],['Form labels','pass',''],['Focus states','pass',''],['Meta description','warn','Shorter than 70 characters'],['Page weight','pass','']];
  let ts = [], res = [];
  const label = { pass:'Pass', warn:'Warning', fail:'Failed' };
  function summary(){
    const c = { pass:0, warn:0, fail:0 }; res.forEach(r => r && c[r]++);
    swapText(sum, `${c.pass} passed, ${c.warn} warnings, ${c.fail} failed`);
  }
  function run(){
    ts.forEach(clearTimeout); ts = []; res = [];
    bar.innerHTML = checks.map(() => '<i></i>').join('');
    list.innerHTML = checks.map((c, i) => `<div class="lc-row" data-i="${i}"><span class="st">${ic('description','sm s-wait')}</span><span>${c[0]}<span class="note"></span></span><span class="r"></span></div>`).join('');
    swapText(sum, 'Running');
    const rows = $$('.lc-row', list), segs = $$('i', bar);
    checks.forEach((c, i) => {
      ts.push(setTimeout(() => { rows[i].querySelector('.st').innerHTML = '<i class="spin"></i>'; swapText(sum, `Running ${i + 1} of ${checks.length}`); }, 300 + i * 520));
      ts.push(setTimeout(() => finish(i, c[1], c[2]), 300 + i * 520 + 420));
    });
    ts.push(setTimeout(() => { summary(); ambient('c34', 'done'); }, 300 + checks.length * 520 + 300));
  }
  function finish(i, r, note){
    res[i] = r; const row = $$('.lc-row', list)[i], seg = $$('i', bar)[i];
    row.classList.add('ran'); seg.className = r;
    row.querySelector('.st').innerHTML = ic(r === 'pass' ? 'check_circle' : r === 'warn' ? 'nearby_error' : 'error', 'sm icon-in ' + (r === 'pass' ? 's-done' : r === 'warn' ? 's-run' : 's-fail'));
    row.querySelector('.note').textContent = note;
    row.querySelector('.r').innerHTML = `<span class="res ${r}">${label[r]}</span>` + (r === 'fail' ? '<button class="retry">Fix</button>' : '');
    const fix = row.querySelector('.retry');
    if (fix) fix.addEventListener('click', () => { Sound.play('tab'); row.querySelector('.st').innerHTML = '<i class="spin"></i>'; fix.remove(); setTimeout(() => { finish(i, 'pass', 'Link updated to the new URL'); summary(); Sound.play('done'); }, 1000); });
    ambient('c34', r === 'pass' ? 'tick' : r === 'fail' ? 'fail' : 'pop');
  }
  $('#lc-run').addEventListener('click', () => { Sound.play('tab'); run(); });
  bar.innerHTML = checks.map(() => '<i></i>').join('');
  list.innerHTML = checks.map(c => `<div class="lc-row"><span class="st">${ic('description','sm s-wait')}</span><span>${c[0]}</span></div>`).join('');
  whenSeen($('#c34'), run);
}
